// Ember's owner-only client. Remote text is escaped; credentials never enter localStorage.
const root = document.querySelector('#app');
const modal = document.querySelector('#modal');
let state, csrf = '', activeCard = null, busy = false, routeEpoch = 0;
const filters = {q:'', status:'all', language:'', set:'', year:'', finish:'', sort:'year-desc', price:'', page:1};
const e = value => String(value ?? '').replace(/[&<>"']/g, x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const money = (value,currency=state?.preferences.currency || 'EUR') => value == null ? 'Unknown' : new Intl.NumberFormat('en-GB',{style:'currency',currency,maximumFractionDigits:currency==='JPY'?0:2}).format(Number(value));
const dt = value => value ? new Date(value).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}) : 'Not yet checked';
const pct = (a,b) => b ? (100*a/b).toFixed(1) : '0.0';
const tag = (s,cls='')=>`<span class="tag ${e(cls)}">${e(s)}</span>`;
const opt = (value,label,current)=>`<option value="${e(value)}" ${String(value)===String(current)?'selected':''}>${e(label)}</option>`;
const currencies = c => [...(state?.currencies || ['EUR','USD','GBP','JPY','CHF','CAD','AUD'])].map(x=>opt(x,x,c)).join('');
const act = (action,label,cls='button-outline',data='')=>`<button type="button" class="${cls}" data-action="${action}" ${data}>${label}</button>`;
const empty = (title,text,button='')=>`<div class="empty"><div class="empty-icon">—</div><h3>${e(title)}</h3><p>${e(text)}</p>${button}</div>`;
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),4500);}
async function api(path,options={}){
  const headers={...options.headers};
  if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  if(options.method && options.method!=='GET')headers['X-CSRF-Token']=csrf;
  const r=await fetch(path,{...options,headers,credentials:'same-origin'});
  let data;try{data=await r.json();}catch{throw new Error(`Server returned an unreadable response (${r.status}).`);}
  if(!r.ok){if(r.status===401 && path!=='/api/login'){state=null;csrf='';loginView();}throw new Error(data.errors?.map(x=>`${x.field}: ${x.message}`).join('\n') || (typeof data.detail==='string'?data.detail:JSON.stringify(data.detail)) || `Request failed (${r.status})`);}
  return data;
}
function image(v,large=false){const imageUrl=v.reference_image?'/static/cards/'+encodeURIComponent(v.reference_image):v.image_url;return `<div class="card-image ${imageUrl?'':'image-missing'}"><div class="card-fallback"><strong>004</strong><span>${e(v.name)}</span><small>Reference artwork unavailable</small></div>${imageUrl?`<img src="${e(imageUrl)}" alt="${e(v.name)} — ${e(v.set_name)} ${e(v.number)} reference artwork" loading="${large?'eager':'lazy'}" referrerpolicy="no-referrer">`:''}</div>`;}
function attachImages(){document.querySelectorAll('.card-image img').forEach(img=>{img.addEventListener('load',()=>{img.parentElement.classList.add('image-ready');img.parentElement.classList.remove('image-missing');},{once:true});if(img.complete&&img.naturalWidth)img.parentElement.classList.add('image-ready');img.addEventListener('error',()=>img.parentElement.classList.add('image-missing'),{once:true});if(img.complete&&!img.naturalWidth)img.parentElement.classList.add('image-missing');});}
function cardTile(v){const status=v.status||'Missing';return `<article class="card ${v.psa10_owned?'card-owned':''} ${status==='Alternative'?'card-alternative':''}"><a href="#card/${e(v.id)}" aria-label="Open ${e(v.name)} ${e(v.set_name)} ${e(v.number)} ${e(v.edition)} ${e(v.finish)}">${image(v)}</a><div class="card-body"><a class="card-title" href="#card/${e(v.id)}">${e(v.name)}</a><p class="card-set">${e(v.set_name)} · ${e(v.number)}</p><div class="card-meta"><span>${e(v.language.toUpperCase())}</span><span>${e(v.finish==='unspecified'?'Print unresolved':v.finish)}</span>${v.edition!=='standard'?`<span>${e(v.edition)}</span>`:''}${v.print_run!=='standard'?`<span>${e(v.print_run)}</span>`:''}${v.stamp!=='none'?`<span>${e(v.stamp)}</span>`:''}</div><div class="card-status">${tag(status==='Owned'?'PSA 10 owned':status==='Alternative'?'Upgrade needed':status,status.toLowerCase())}<span class="muted">${status==='Alternative'?'Owned alternative · PSA 10 missing':v.identity_status==='documented'?(v.availability?.verified?`${v.availability.verified} reviewed PSA 10 offer(s)`:'PSA 10 availability unknown'):'Identity needs review'}</span></div></div></article>`;}
function loginView(error=''){
  root.innerHTML=`<div class="login-layout"><section class="login-art"><div class="brand"><span class="brand-symbol">e.</span><div><strong>ember</strong><small>The Charmander collection</small></div></div><div class="eyebrow">One Pokémon. Every detail.</div><h1>A collection<br>worth knowing.</h1><p>Your personal binder for Charmander. Exact printings, PSA 10 upgrades, raw alternatives, and buying decisions grounded in evidence.</p></section><main class="login-form"><div class="eyebrow">Private collection</div><h2>Welcome to your binder.</h2><p>Sign in with the owner password you configured during setup. There is no public registration.</p><form id="login-form"><label class="field">Owner password<input name="password" type="password" required autocomplete="current-password" maxlength="1024"></label><p class="form-error" id="login-error">${e(error)}</p><button class="button" type="submit">Open collection <span>↗</span></button></form><p class="login-foot">Protected access · Persistent collection · Manual purchasing<br>NM/Mint and PSA 10 · Your data stays on this computer.</p></main></div>`;
}
function shell(content){
 const page=(location.hash.slice(1)||"dashboard").split("/")[0];
 const items=[['dashboard','⌂','Overview'],['collection','▦','The collection'],['watchlist','☆','Watchlist'],['plan','◎','Purchase planner'],['deals','◇','Buying opportunities'],['alerts','◉','Alerts'],['settings','⚙','Settings']];
 return `<div class="shell"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-symbol">e.</span><div><strong>ember</strong><small>Charmander collection</small></div></a><div class="eyebrow">Your binder</div><nav class="nav" aria-label="Main navigation">${items.map(([key,icon,label])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${key==='alerts'&&state.alerts_unread?`<span class="count">${state.alerts_unread}</span>`:''}</a>`).join('')}</nav><div class="sidebar-foot">${tag('PSA GEM MINT 10')}<strong>The details make the collection.</strong>Exact identities. Transparent evidence. No automatic purchases.<button data-action="logout">Sign out ↗</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Your collection <span>/ ${e(page==='card'?'Card details':items.find(x=>x[0]===page)?.[2]||page)}</span></div><div class="top-actions"><span class="private">Owner-private</span><button data-action="refresh">↻ Refresh data</button><span class="avatar" title="Owner session">AG</span></div></header><main class="content" id="main" tabindex="-1">${content}</main></div></div>`;
}
function coverageNotice(){return `<div class="notice info">Partial catalogue · ${state.coverage.catalogue_total} source-linked records · ${state.coverage.resolved} documented printing identities. Current scope: ${state.completion.base_printings} base printings, ${state.completion.total} variants. Unresolved entries remain visible but cannot count as owned. <a href="#settings">Coverage and sources ↗</a></div>`;}
function stats(){const c=state.completion;return `<div class="stats"><div class="stat"><div class="stat-top">PSA 10 COMPLETION</div><strong>${pct(c.owned,c.total)}<small>%</small></strong><small>${c.owned} of ${c.total} variants · ultimate goal</small></div><div class="stat"><div class="stat-top">ANY ENABLED CONDITION</div><strong>${pct(c.any_owned,c.total)}<small>%</small></strong><small>${c.any_owned} variants · multiple copies count once</small></div><div class="stat"><div class="stat-top">PSA 10 UPGRADES NEEDED</div><strong>${c.upgrade_needed}</strong><small>Owned alternative · PSA 10 still missing</small></div><div class="stat"><div class="stat-top">BUDGET REMAINING</div><strong>${state.budget.limit==null?'Not set':money(state.budget.remaining)}</strong><small>${state.budget.unknown_cost_copies?`${state.budget.unknown_cost_copies} records have unknown costs`:'Owned and ordered costs included'}</small></div></div>`;}
function groupProgress(field){return Object.entries(state.completion.groups[field]).sort((a,b)=>b[1].total-a[1].total).slice(0,6).map(([name,g])=>`<div class="list-row"><div><strong>${e(field==='language'?state.languages[name]:name)}</strong><p>${g.owned} PSA 10 · ${g.any_owned} any-condition · ${g.total} catalogued${g.provisional?` · ${g.provisional} unresolved`:''}</p></div><progress class="progress group-progress" max="${g.total||1}" value="${g.owned}" aria-label="${e(name)} PSA 10 completion"></progress></div>`).join('');}
async function dashboard(){
 const {deals}=await api('/api/deals');const good=deals.filter(d=>d.listing.assessment.label==='Good buying opportunity'&&d.listing.assessment.within_budget);
 const c=state.completion;const picks=[...state.variants].sort((a,b)=>(b.identity_status==='documented')-(a.identity_status==='documented')||Boolean(b.image_url)-Boolean(a.image_url)||(b.year||0)-(a.year||0)).slice(0,4);
 return `<div class="page-heading"><div><div class="eyebrow">The Charmander collection · No. 0004</div><h1>Your collection, in perspective.</h1><p>Every printing has a place. Every purchase has a reason.</p></div><a class="button-outline" href="#collection">Open the binder ↗</a></div><section class="hero"><div><div class="eyebrow">Your next chapter</div><h2>${c.owned?'A little closer to every Charmander.':'Every great collection starts with one.'}</h2><p>${c.owned?'Explore missing printings, compare evidence, and choose the next addition on your terms.':'Start with an exact printing, record your first copy, and keep PSA 10 as the ultimate goal.'}</p><a class="button" href="#collection">Explore your checklist ↗</a></div><div class="hero-aside"><div class="hero-number">${c.owned}<small> / ${c.total}</small></div><p>PSA 10 variants collected<br>Current scope · ${state.preferences.languages.length} selected languages</p><progress class="progress" value="${c.owned}" max="${c.total||1}" aria-label="Overall collection completion"></progress><p>${pct(c.owned,c.total)}% of the current, partial checklist</p></div></section>${stats()}<div class="section-head"><h2>A place in your binder</h2><a href="#collection">View all ${c.total} records ↗</a></div><div class="grid grid-feature">${picks.map(cardTile).join('')}</div>${coverageNotice()}<div class="two-col"><section class="panel"><div class="section-head no-margin"><h2>Worth a closer look</h2><a href="#deals">All opportunities ↗</a></div>${good.length?good.slice(0,3).map(d=>`<div class="list-row"><div><a href="#card/${e(d.card.id)}">${e(d.card.set_name)} · ${e(d.card.number)}</a><p>${d.listing.assessment.market.count} comparable sales · ${d.listing.assessment.price_confidence} confidence</p></div><strong>${money(d.listing.assessment.cost.total)}</strong></div>`).join(''):empty('No supported bargains yet','Add real listings and completed-sale evidence, then review the exact slab. Uncertain prices never become recommendations.',`<a class="button-outline button-small" href="#settings">Manage sources</a>`)}</section><section class="panel"><h2>Across languages</h2>${groupProgress('language')}</section></div><div class="two-col"><section class="panel"><h2>Set by set</h2>${groupProgress('set_name')}</section><section class="panel"><h2>Recent activity</h2>${state.activity.length?state.activity.slice(0,6).map(a=>`<div class="timeline-row"><span class="timeline-dot"></span><div><p>${e(a.message)}</p><time>${e(dt(a.time))}</time></div></div>`).join(''):empty('A clean start','No ownership or marketplace records have been invented. Your activity appears here as you use Ember.')}</section></div><p class="footnote">${state.preferences.paused?'Monitoring is paused. Enable it in Settings.':`Monitoring checks every ${state.preferences.refresh_hours} hours while the server is running.`} Last updater execution: ${dt(state.monitor?.checkedAt)}. This is not proof of a completed marketplace scan.</p>`;
}
function binder(){
 const unique=key=>[...new Set(state.variants.map(v=>v[key]).filter(Boolean))].sort();
 return `${savedSearchControls()}<div class="page-heading"><div><div class="eyebrow">A personal archive</div><h1>The collection.</h1><p>Your visual checklist of exact printings. Missing artwork stays identifiable; no listing is required for a card to belong here.</p></div><div class="actions">${act('import','Import CSV')}${act('add-variant','Add a printing','button')}</div></div><div class="tabs" role="group" aria-label="Ownership filter">${['all','Owned','Alternative','Missing','Watchlist','Ordered'].map(s=>`<button data-action="status-filter" data-value="${s}" class="${filters.status===s?'active':''}">${s==='all'?'All cards':s==='Owned'?'PSA 10 owned':s==='Alternative'?'Upgrade needed':s}</button>`).join('')}</div><div class="section-head"><span>${state.completion.owned} owned · ${pct(state.completion.owned,state.completion.total)}% of current scope</span><a href="/api/export/copies">Export collection ↧</a></div><div class="filters"><input class="search" id="filter-q" data-filter="q" placeholder="Search a set, card number, stamp…" aria-label="Search collection" value="${e(filters.q)}"><select data-filter="language" aria-label="Filter language">${opt('','All languages',filters.language)}${unique('language').map(x=>opt(x,state.languages[x],filters.language)).join('')}</select><select data-filter="set" aria-label="Filter set">${opt('','All sets',filters.set)}${unique('set_name').map(x=>opt(x,x,filters.set)).join('')}</select><select data-filter="year" aria-label="Filter year">${opt('','All years',filters.year)}${unique('year').reverse().map(x=>opt(x,x,filters.year)).join('')}</select><select data-filter="finish" aria-label="Filter finish">${opt('','All finishes',filters.finish)}${unique('finish').map(x=>opt(x,x,filters.finish)).join('')}</select><select data-filter="sort" aria-label="Sort cards">${[['year-desc','Newest first'],['year-asc','Oldest first'],['set','Set name'],['price','Lowest reviewed asking price'],['status','Ownership status']].map(([v,n])=>opt(v,n,filters.sort)).join('')}</select><input class="number" data-filter="price" type="number" min="0" placeholder="Max asking price" aria-label="Maximum verified asking price" value="${e(filters.price)}"></div><div id="binder-results"></div>${coverageNotice()}`;
}
function renderBinderResults(){const el=document.querySelector('#binder-results');if(!el)return;let vs=state.variants.filter(v=>{
 const search=[v.name,v.set_name,v.set_code,v.number,v.stamp,v.edition,v.finish,v.id].join(' ').toLowerCase();
 return (!filters.q||search.includes(filters.q.toLowerCase()))&&(filters.status==='all'||(filters.status==='Missing'?v.status!=='Owned':v.status===filters.status))&&(!filters.language||v.language===filters.language)&&(!filters.set||v.set_name===filters.set)&&(!filters.year||String(v.year)===filters.year)&&(!filters.finish||v.finish===filters.finish)&&(!filters.price||(v.availability?.price!=null&&v.availability.price<=Number(filters.price)));});
 vs.sort((a,b)=>filters.sort==='year-asc'?(a.year||9999)-(b.year||9999):filters.sort==='set'?a.set_name.localeCompare(b.set_name):filters.sort==='status'?a.status.localeCompare(b.status):filters.sort==='price'?(a.availability?.price??1e12)-(b.availability?.price??1e12):(b.year||0)-(a.year||0));
 const pages=Math.max(1,Math.ceil(vs.length/24));filters.page=Math.min(filters.page,pages);const shown=vs.slice((filters.page-1)*24,filters.page*24);
 el.innerHTML=`<div class="filter-footer"><span>${vs.length} matching records</span><span>PSA 10 goal · alternatives tracked separately · ${e(state.preferences.currency)}</span></div>${shown.length?`<div class="grid">${shown.map(cardTile).join('')}</div>`:empty('No cards in this view','Change the filters or collection scope. Other languages may need catalogue synchronization.')}<div class="pagination">${act('page-prev','← Previous','button-outline button-small')}<span>Page ${filters.page} of ${pages}</span>${act('page-next','Next →','button-outline button-small')}</div>${filters.price?'<p class="footnote">Price filter uses fresh, reviewed fixed-price asks in your currency. It does not treat auction bids, shipping or an unknown conversion as a known price.</p>':''}`;
 attachImages();}
function priceChart(market){const sales=market.included.slice().sort((a,b)=>a.sold_date.localeCompare(b.sold_date));if(!sales.length)return empty('No eligible completed-sale observations','Add disclosed transactions for this exact variant and condition. Other grades and asking prices do not fill this chart.');return scatterChart(sales.map(s=>({date:s.sold_date,value:s.converted_price,label:`Completed sale · ${s.source} · ${s.sold_date}`})),market.currency,'Completed sale observations — no interpolation');}
function salesTable(market){return `<div class="table-wrap"><table><thead><tr><th>Sold / source</th><th>Condition / grade</th><th>Disclosed item price</th><th>Evidence use</th><th></th></tr></thead><tbody>${[...market.included,...market.excluded].map(s=>`<tr><td>${e(s.sold_date)}<br><a href="${e(s.source_url)}" target="_blank" rel="noopener noreferrer">${e(s.source)} ↗</a></td><td>${e(conditionText(s))}</td><td>${s.price_disclosed?money(s.item_price,s.currency):'Undisclosed'}</td><td>${e(s.excluded_reason||'Included · source-linked owner attestation')}</td><td>${act('delete-sale','Remove','button-subtle button-small danger',`data-id="${e(s.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function listingCard(l,vid){const a=l.assessment;const raw=l.grader==='RAW';return `<article class="listing"><div class="listing-head">${l.image_url?`<img class="listing-thumb" src="${e(l.image_url)}" alt="Seller photograph; not authenticated" loading="lazy" referrerpolicy="no-referrer">`:''}<div class="listing-title"><h3><a href="${e(l.url)}" target="_blank" rel="noopener noreferrer">${e(l.title)} ↗</a></h3><p>${e(l.source)} · ${e(l.seller||'Seller unknown')} · ${e(l.seller_country||'Location unknown')}${l.seller_feedback!=null?` · ${e(l.seller_feedback)}% feedback`:''}</p><div class="actions">${tag(l.condition_label||conditionText(l),'orange')}${tag(l.listing_type==='auction'?'Auction · current bid':'Fixed price')}${tag(l.status)}${l.cross_post_group?tag('Same-slab cross-post group'):''}</div></div><div class="listing-price"><strong>${money(l.price,l.currency)}</strong><small>${l.listing_type==='auction'?'Current bid · final price unknown':'Item asking price'}</small></div></div><div class="cost-strip"><div><span>Estimated delivered cost</span><strong>${a.cost.total!=null?money(a.cost.total):a.cost.lower_bound!=null?'At least '+money(a.cost.lower_bound):'Unknown'}</strong></div><div><span>Exact-condition market reference</span><strong>${a.market.reference!=null?money(a.market.reference):'Insufficient data'}</strong></div><div><span>Assessment</span>${tag(a.label,a.label==='Good buying opportunity'?'green':'')}</div></div><p class="explanation">${e(a.explanation)}</p><p class="footnote">Original condition: ${e(l.condition_original||'Not supplied')} · identity: ${e(a.match_confidence)} · condition: ${e(a.condition_confidence)} · price: ${e(a.price_confidence)}. Checked ${e(dt(l.checked_at))}.</p>${a.within_target?`<div class="notice info">Within your ${money(a.target_price)} delivered-price target. This is not necessarily below market value.</div>`:''}<details class="evidence"><summary>Costs, matching checks & valuation evidence</summary><dl class="evidence-dl"><dt>Shipping</dt><dd>${money(l.shipping,l.currency)}</dd><dt>Fees</dt><dd>${money(l.fees,l.currency)}</dd><dt>Import costs</dt><dd>${money(l.import_cost,l.currency)}</dd><dt>Destination / delivery</dt><dd>${e(l.destination_country)} · ${l.delivery_eligible===true?'owner/provider stated eligible':l.delivery_eligible===false?'not eligible':'unknown'}</dd><dt>FX</dt><dd>${a.cost.fx?e(a.cost.fx.date+' · '+a.cost.fx.source):'Same currency or unavailable'}</dd><dt>Unknown costs</dt><dd>${e(a.cost.unknown.join(', ')||'None recorded')}</dd></dl><p>${e(l.cost_notes||'Verify tax treatment at checkout. Enter zero only when actually known; do not double-count included taxes.')}</p><p>${e((l.match.reasons||[]).concat(l.match.missing||[]).join('; '))}</p><p>${e(a.market.method)}</p><p>${a.market.count} eligible completed sales · ${a.market.excluded.length} excluded observations · weighted effective sample ${a.market.effective_count}.</p>${a.market.included.length?salesTable(a.market):''}</details><div class="actions"><a class="button-outline button-small" href="${e(l.url)}" target="_blank" rel="noopener noreferrer">${l.listing_type==='auction'?'View auction':'Buy on '+e(l.source)} ↗</a>${act('review-listing',raw?'Review exact card':'Review exact slab','button-outline button-small',`data-id="${e(l.id)}" data-vid="${e(vid)}"`)}${act('edit-listing','Update observation','button-subtle button-small',`data-id="${e(l.id)}" data-vid="${e(vid)}"`)}${act('unavailable','Mark unavailable','button-subtle button-small',`data-id="${e(l.id)}"`)}</div></article>`;}
async function detailPage(id){const d=await api('/api/cards/'+encodeURIComponent(id));activeCard=d;const v=d.card;const s=state.variants.find(x=>x.id===id)?.status||'Missing';return `<div class="page-heading"><div><div class="eyebrow"><a href="#collection">← Back to the collection</a></div><h1>${e(v.name)}</h1><p>${e(v.set_name)} · ${e(v.number)} · ${e(state.languages[v.language])}</p></div><div class="actions">${tag(s,s.toLowerCase())}${tag(v.identity_status,v.identity_status==='documented'?'green':'orange')}</div></div><div class="detail-grid"><aside class="detail-card">${image(v,true)}<p class="footnote">${e(v.image_note||"Reference artwork; finishes, languages and stamps may differ from this printing.")}</p><div class="actions">${act('add-copy','Record a copy','button',`data-vid="${e(id)}"`)}${act('watch','Set a target','button-outline',`data-vid="${e(id)}"`)}</div>${v.identity_status==='provisional'?`<div class="notice">Document the physical printing before ownership or recommendations. ${act('resolve-variant','Document exact printing','button-outline button-small',`data-vid="${e(id)}"`)}</div>`:''}<section class="panel search-links"><h3>Search other sources</h3><p class="footnote">External searches, not verified listings or scanned prices.</p>${d.research_links.map(x=>`<a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.source)} ↗</a>`).join('')}</section></aside><div><section class="panel detail-info"><h2>The exact printing</h2><dl><dt>Set / number</dt><dd>${e(v.set_name)} / ${e(v.number)}</dd><dt>Release year</dt><dd>${v.year||'Not verified'}</dd><dt>Edition</dt><dd>${e(v.edition)}</dd><dt>Finish</dt><dd>${e(v.finish)}</dd><dt>Stamp</dt><dd>${e(v.stamp)}</dd><dt>Print run / size</dt><dd>${e(v.print_run)} / ${e(v.size)}</dd><dt>Stable identity</dt><dd><code>${e(id)}</code></dd><dt>Source</dt><dd><a href="${e(v.source_url)}" target="_blank" rel="noopener noreferrer">Catalogue documentation ↗</a> · ${e(v.source_checked_at.slice(0,10))}</dd></dl>${v.notes?`<p class="notice info">${e(v.notes)}</p>`:''}${d.variants.filter(x=>!x.retired&&x.id!==id).length?`<details><summary>Other printings of this card</summary><div class="actions">${d.variants.filter(x=>!x.retired&&x.id!==id).map(x=>`<a href="#card/${e(x.id)}" class="button-outline button-small">${e(x.edition+' · '+x.finish+' · '+x.stamp+' · '+x.print_run)}</a>`).join('')}</div></details>`:''}</section><section class="panel"><div class="section-head no-margin"><h2>Your copies</h2>${act('add-copy','Add a copy','button-outline button-small',`data-vid="${e(id)}"`)}</div>${d.copies.length?d.copies.map(c=>`<div class="list-row">${c.photo_key?`<img class="slab-photo" src="/api/photos/${e(c.photo_key)}" alt="Private photograph of your actual copy">`:''}<div><strong>${tag(c.status,c.status.toLowerCase())} ${e(conditionText(c))}</strong><p>${e(c.cert||'Ungraded / certificate pending')} · ${e(c.purchase_date||'Date not recorded')} · ${e(c.seller||'Seller not recorded')}</p><p>Item cost ${money(c.purchase_price,c.currency)} · ${e(c.notes)}</p><div class="actions">${act('edit-copy','Edit','button-subtle button-small',`data-id="${e(c.id)}"`)}${act('photo','Add photo','button-subtle button-small',`data-id="${e(c.id)}"`)}${act('delete-copy','Remove','button-subtle button-small danger',`data-id="${e(c.id)}"`)}</div></div></div>`).join(''):empty('No copies recorded','Track a PSA 10 slab or an explicitly identified alternative. Ordered copies do not count as owned.')}${s==='Alternative'?'<div class="notice info">Owned as an alternative — PSA 10 still missing. Upgrade monitoring continues.</div>':''}${d.watch?`<div class="notice info">On your watchlist · priority ${d.watch.priority}/5 · ${Object.keys(d.watch.targets||{}).length} condition-specific targets. ${act('watch','Edit targets','button-subtle button-small')}${act('unwatch','Remove watch','button-subtle button-small',`data-vid="${e(id)}"`)}</div>`:''}</section><section class="panel"><div class="section-head no-margin"><h2>Buy this card</h2><div class="actions">${act('scan-card','Scan this card','button-outline button-small',`data-vid="${e(id)}"`)}${act('add-listing','Add a listing','button-outline button-small',`data-vid="${e(id)}"`)}</div></div><div class="notice info">${e(d.psa10_summary)}</div><p class="footnote">${e(d.ranking_method)} Best found among recorded/scanned sources—not the entire internet.</p>${d.scan_coverage?`<p class="footnote">eBay scan: ${e(dt(d.scan_coverage.checked_at))} · ${d.scan_coverage.results} candidates · ${d.scan_coverage.truncated?'truncated':'bounded query completed'} · ${e(d.scan_coverage.country)}. ${d.scan_current?'':'This scan is stale or for different settings.'}</p>`:''}${comparisonTable(d)}${d.listings.length?d.listings.filter(l=>l.listing_type==='fixed').map(l=>listingCard(l,id)).join(''):empty('No real listings recorded','Connect an eligible source or enter a real listing. Missing data is never replaced with demonstration offers.')}<details class="auction-section"><summary>Auctions — current bids, never final acquisition prices (${d.listings.filter(l=>l.listing_type==='auction').length})</summary>${d.listings.filter(l=>l.listing_type==='auction').map(l=>listingCard(l,id)).join('')}</details></section><section class="panel"><div class="section-head no-margin"><h2>Completed-sale evidence</h2>${act('add-sale','Add a sale','button-outline button-small',`data-vid="${e(id)}"`)}</div><label class="field">Historical condition / grade<select id="history-bucket" aria-label="Historical condition / grade">${Object.entries(d.markets).map(([k,m])=>opt(k,m.condition_label,historySelection&&d.markets[historySelection]?historySelection:'graded:PSA:10:Gem Mint:current')).join('')}</select></label><div id="condition-history">${historyPanel(d,historySelection&&d.markets[historySelection]?historySelection:'graded:PSA:10:Gem Mint:current')}</div></section><section class="panel"><div class="section-head no-margin"><h2>Price-guide context</h2><div class="actions">${act('public-guides','Refresh free public guides','button-outline button-small',`data-vid="${e(id)}"`)}${act('pricecharting-product','PriceCharting product','button-outline button-small',`data-vid="${e(id)}"`)}</div></div><p class="notice info">Third-party aggregate estimates are not completed transactions and never drive bargain labels. Generic ungraded estimates are not a Near Mint valuation.</p>${d.aggregate_observations.length?`<div class="table-wrap"><table><thead><tr><th>Observed</th><th>Provider group</th><th>Aggregate estimate</th></tr></thead><tbody>${d.aggregate_observations.map(o=>`<tr><td><a href="${e(o.source_url)}" target="_blank" rel="noopener noreferrer">${e(dt(o.observed_at))} ↗</a></td><td>${e(o.source)} · ${e(o.condition_label)}${o.provider_updated_at?`<small class="block footnote">Provider update: ${e(dt(o.provider_updated_at))}</small>`:''}</td><td>${money(o.amount,o.currency)}</td></tr>`).join('')}</tbody></table></div>`:empty('No connected price-guide observations','Use the free TCGdex public guides, or an existing licensed PriceCharting token. Base-card mapping requires review. Aggregate estimates cannot replace exact-condition sales.')}</section></div></div>`;}
async function dealsPage(){const data=await api('/api/deals');dealRows=data.deals;return `<div class="page-heading"><div><div class="eyebrow">Best found, with evidence</div><h1>Buying opportunities.</h1><p>PSA 10 upgrades first; enabled alternatives in separate condition buckets.</p></div>${act('monitor','Refresh listings','button')}</div><div class="notice info">${e(state.sources.ebay.message)} Results cover recorded/scanned sources only. Auctions are not immediately purchasable bargains.</div><div class="filters deals-filters"><label class="field">Card / set<input data-deal-filter="q" placeholder="Search opportunities" value="${e(dealFilters.q)}"></label><label class="field">Grader / raw<select aria-label="Grader / raw" data-deal-filter="grader">${['','PSA','BGS','CGC','RAW'].map(x=>opt(x,x||'All enabled',dealFilters.grader)).join('')}</select></label><label class="field">Exact condition<select aria-label="Exact condition" data-deal-filter="condition">${opt('','All enabled',dealFilters.condition)}${conditionOptions(dealFilters.condition)}</select></label><label class="field">Language<select aria-label="Language" data-deal-filter="language">${opt('','All',dealFilters.language)}${Object.entries(state.languages).map(([k,v])=>opt(k,v,dealFilters.language)).join('')}</select></label><label class="field">Offer type<select aria-label="Offer type" data-deal-filter="type">${opt('','All (auctions marked)',dealFilters.type)}${opt('fixed','Fixed price',dealFilters.type)}${opt('auction','Auction bid',dealFilters.type)}</select></label><label class="field">Maximum total<input type="number" min="0" data-deal-filter="max" value="${e(dealFilters.max)}"></label><label class="field">Seller country<input maxlength="2" data-deal-filter="country" value="${e(dealFilters.country)}" placeholder="BE / FR / …"></label><label class="field">Price evidence<select aria-label="Price evidence" data-deal-filter="confidence">${['','high','medium','low','none'].map(x=>opt(x,x||'All levels',dealFilters.confidence)).join('')}</select></label></div><div id="deal-results">${dealResults()}</div><p class="footnote">Targets are condition-specific. Recommendations are not return forecasts, authenticity guarantees, combined basket reservations or automatic purchases.</p>`;}
async function alertsPage(){const {alerts}=await api('/api/alerts');return `<div class="page-heading"><div><div class="eyebrow">Only when something changes</div><h1>Your alerts.</h1><p>Targets and evidence-led bargains, deduplicated by listing, exact variant, destination, currency, and total cost.</p></div>${act('read-alerts','Mark all read')}</div>${alerts.length?alerts.map(a=>`<section class="panel"><div class="section-head no-margin"><h2><a href="#card/${e(a.variant_id)}">${e(a.name)} · ${e(a.number)}</a></h2>${tag(a.read?'Read':'New',a.read?'':'orange')}</div><p>${e(a.set_name)} · ${e(a.condition_label||'PSA 10')} · ${dt(a.created_at)}</p><h2>${money(a.cost.total,a.cost.currency)}</h2><p>${e(a.reason)}</p><div class="notice info">Match: ${e(a.match_confidence)} · Price: ${e(a.price_confidence)}. Recheck availability and costs before acting.</div><a class="button-outline" href="${e(a.url)}" target="_blank" rel="noopener noreferrer">Open listing ↗</a></section>`).join(''):empty('Nothing to notify you about yet','Set a delivered-price target or add comparable sale evidence. Enable monitoring in Settings when ready. Unchanged listings do not repeatedly notify you.')}`;}
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${e(label)}<input name="${e(name)}" type="${type}" value="${e(value??'')}" ${extra}></label>`;
const selectField=(label,name,options)=>`<label class="field">${e(label)}<select name="${e(name)}" aria-label="${e(label)}">${options}</select></label>`;
const check=(label,name,checked=false)=>`<label class="check"><input type="checkbox" name="${e(name)}" ${checked?'checked':''}>${e(label)}</label>`;
function baseSettingsPage(){const p=state.preferences;return `<div class="page-heading"><div><div class="eyebrow">Make it your collection</div><h1>Settings & sources.</h1><p>Define the scope, connect supported data, and control what deserves your attention.</p></div>${tag('Rebuilt application · v'+state.version)}</div><form id="settings-form"><div class="settings-grid"><section class="panel wide"><h2>Collection scope</h2><p>Select languages explicitly. Selecting a language with no records exposes a coverage gap; it does not invent translations or printings.</p><hr class="divider"><div class="checks">${Object.entries(state.languages).map(([key,name])=>`<label class="check"><input name="languages" value="${key}" type="checkbox" ${p.languages.includes(key)?'checked':''}>${e(name)}</label>`).join('')}</div><hr class="divider"><div class="form-grid"><div class="field full">Limit release types (none selected = all)<div class="checks">${['Expansion','Promo','Deck','Jumbo'].map(x=>`<label class="check"><input type="checkbox" name="release_types" value="${x}" ${p.release_types.includes(x)?'checked':''}>${x}</label>`).join('')}</div></div>${field('Specific finishes (comma-separated; blank = all)','finishes','text',p.finishes.join(', '))}${field('Editions (comma-separated; blank = all)','editions','text',p.editions.join(', '))}${field('Stamps (comma-separated; blank = all)','stamps','text',p.stamps.join(', '))}${selectField('Card size','sizes',opt('','All sizes',p.sizes[0]||'')+opt('standard','Standard only',p.sizes[0])+opt('jumbo','Jumbo only',p.sizes[0]))}${check('Include artwork-only cameos (coverage not audited)','artwork_only',p.artwork_only)}${check('Include announced future releases','include_announced',p.include_announced)}</div></section><section class="panel"><h2>Location & budget</h2><div class="form-grid">${field('Destination country (ISO code)','country','text',p.country,'required minlength="2" maxlength="2" pattern="[A-Z]{2}"')}${selectField('Display currency','currency',currencies(p.currency))}${field('Total collection budget (optional)','budget','number',p.budget,'min="0" step="0.01"')}${selectField('eBay marketplace','ebay_marketplace',['EBAY_FR','EBAY_DE','EBAY_GB','EBAY_US','EBAY_BE','EBAY_CA','EBAY_AU','EBAY_IT','EBAY_ES','EBAY_NL'].map(x=>opt(x,x,p.ebay_marketplace)).join(''))}</div><p class="footnote">Budget includes owned and ordered copies. Unknown costs prevent a reliable remaining budget. Changing destination clears listing delivery estimates.</p></section><section class="panel"><h2>Price evidence</h2><div class="form-grid">${field('Bargain discount (%)','bargain_pct','number',p.bargain_pct,'min="1" max="80" required')}${field('Expensive premium (%)','expensive_pct','number',p.expensive_pct,'min="1" max="100" required')}${field('Minimum eligible completed sales','min_sales','number',p.min_sales,'min="3" max="30" required')}${field('Sale lookback (days)','lookback_days','number',p.lookback_days,'min="7" max="730" required')}${field('Recency half-life (days)','half_life_days','number',p.half_life_days,'min="7" max="365" required')}${field('Listing stale after (hours)','stale_hours','number',p.stale_hours,'min="1" max="168" required')}</div></section><section class="panel wide"><h2>Monitoring & alerts</h2><div class="form-grid">${selectField('Scan scope','monitor_mode',opt('missing','Every missing card',p.monitor_mode)+opt('watchlist','Selected watchlist',p.monitor_mode))}${field('Refresh interval (hours)','refresh_hours','number',p.refresh_hours,'min="1" max="168" required')}${check('Pause monitoring and in-app alerts','paused',p.paused)}${check('Enable in-app notifications','notifications',p.notifications)}</div><div class="notice">The scheduler ${state.scheduler_enabled?'is configured in this server process':'is disabled for this deployment'}. It only runs while the persistent server is running. Last execution: ${dt(state.monitor?.checkedAt)} · ${e(state.monitor?.status||'not observed')}. ${e(state.monitor?.message||'A configured schedule alone does not prove execution.')}</div><div class="actions">${act('monitor','Run updater now')}${act('monitor-history','View execution log')}</div><p class="footnote">Manual refresh can bypass the interval, but never the pause switch. eBay scans at most 10 variants per pass. New candidates need manual slab review before alerts qualify. External email/SMS delivery is not configured.</p></section></div><div id="settings-error" class="form-error"></div><div class="form-footer"><button class="button" type="submit">Save preferences</button></div></form><section class="panel"><h2>Connected sources</h2><div class="source-grid"><div class="source-box"><h3>eBay Browse</h3>${tag(state.sources.ebay.status,state.sources.ebay.status==='connected'?'green':'orange')}<p>Official production OAuth and active-listing API. Eligible credentials required; no completed-sale feed is implied.</p><div class="actions">${act('connect-ebay','Connect / replace','button-outline button-small')}${act('disconnect-ebay','Disconnect','button-subtle button-small')}</div></div><div class="source-box"><h3>Completed sales & specialists</h3>${tag('Manual evidence only')}<p>Source-linked completed sales and specialist listings can be entered on each card or imported by CSV. No automatic Cardmarket or auction feed is connected.</p>${act('import','Import evidence','button-outline button-small')}</div><div class="source-box"><h3>Reference FX</h3>${tag(state.sources.fx.status)}<p>${state.fx?`Rates dated ${e(state.fx.date)}. ${e(state.fx.source)}.`:'No rates fetched. Same-currency calculations work without FX.'} Stale rates are not used.</p>${act('refresh-fx','Refresh rates','button-outline button-small')}</div></div><p class="footnote">Credentials are encrypted server-side. Never put credentials in CSV files, catalogue notes, repository commits or collection exports.</p></section><section class="panel"><h2>Catalogue coverage</h2><p>${state.coverage.catalogue_total} records · ${state.coverage.resolved} documented identities · ${state.coverage.languages.map(l=>e(state.languages[l])).join(', ')} represented. Seed checked ${e(state.coverage.seed?.checked_at)}.</p><div class="notice info">${state.coverage.gaps.map(e).join('<br>')}</div><div class="actions"><select id="catalogue-language" aria-label="Language to synchronize">${Object.entries(state.languages).map(([k,v])=>opt(k,v,'en')).join('')}</select>${act('sync-catalogue','Sync next catalogue batch')}${act('add-variant','Add documented printing')}</div><p class="footnote">TCGdex sync processes 30 base cards per batch and preserves your records. Imported printings stay provisional until their physical identity is resolved. A provider pass is not proof of complete worldwide coverage.</p>${state.coverage.sync.map(x=>`<div class="notice">${e(x.language)}: ${e(x.status)} · ${x.processed||0} processed · ${x.added||0} added. ${e((x.errors||[]).join(' '))}</div>`).join('')}</section><section class="panel"><h2>Mac app & backups</h2><p>Scans run while Ember is open and monitoring is enabled. Closing the app or putting your Mac to sleep pauses scans. Enable notifications in macOS for desktop alerts.</p><p>A full backup includes your collection, photographs and matching private configuration. Keep it somewhere secure.</p><a href="/api/backup" class="button-outline" download>Download full private backup ↧</a></section><section class="panel"><h2>Data portability</h2><p>Exports contain your records and stable variant IDs, not credentials or private photos. Back up the runtime database separately on your own storage.</p><div class="actions">${['copies','watchlist','listings','sales'].map(kind=>`<a class="button-outline button-small" href="/api/export/${kind}">Export ${kind} ↧</a>`).join('')}${act('import','Import CSV','button-subtle button-small')}</div></section>`;}

let modalSubmit = null;
function openModal(title, description, content, handler=null, submitLabel='Save') {
  modalSubmit = handler;
  document.querySelector('#modal-content').innerHTML = `<div class="modal-head"><h2 id="modal-title">${e(title)}</h2>${act('close-modal','×','button-subtle','aria-label="Close dialog"')}</div><p class="modal-description">${e(description)}</p>${handler?`<form id="modal-form">${content}<div id="modal-error" class="form-error" role="alert"></div><div class="form-footer">${act('close-modal','Cancel')}<button class="button" type="submit">${e(submitLabel)}</button></div></form>`:content}`;
  modal.setAttribute('aria-labelledby','modal-title');
  if(!modal.open)modal.showModal();
}
modal.addEventListener('close',()=>{modalSubmit=null;document.querySelector('#modal-content').replaceChildren();});
function formObject(form){return Object.fromEntries(new FormData(form));}
const nullableNumber=v=>v==null||String(v).trim()===''?null:Number(v);
function costsForm(row={}, purchase=false){return `${field(purchase?'Item purchase price':'Item asking price / current bid',purchase?'purchase_price':'price','number',row[purchase?'purchase_price':'price'],'min="0" step="0.01" '+(purchase?'':'required'))}${selectField('Currency','currency',currencies(row.currency||state.preferences.currency))}${field('Shipping (blank = unknown)','shipping','number',row.shipping,'min="0" step="0.01"')}${field('Fees (blank = unknown)','fees','number',row.fees,'min="0" step="0.01"')}${field('Import cost (blank = unknown)','import_cost','number',row.import_cost,'min="0" step="0.01"')}`;}
const notesField=(value='')=>`<label class="field full">Notes<textarea name="notes" rows="3" maxlength="2000">${e(value)}</textarea></label>`;
function resolvedCard(vid){const v=state.variants.find(x=>x.id===vid)||activeCard?.card;if(!v||v.identity_status!=='documented'){toast('Document the exact printing before recording a copy or completed sale.');return null;}return v;}
function copyModal(vid,existing=null){if(!resolvedCard(vid))return;const c=existing||{};openModal(existing?'Edit this copy':'Record a copy','PSA 10 is the ultimate goal. Other conditions are tracked separately and do not complete that goal.',`<div class="form-grid">${conditionForm(c)}${selectField('Collection state','status',opt('Owned','Owned',c.status||'Owned')+opt('Ordered','Ordered',c.status||'Owned'))}${field('Certification number (graded copies only)','cert','text',c.cert,'maxlength="32"')}${costsForm(c,true)}${field('Purchase date','purchase_date','date',c.purchase_date,`max="${new Date().toISOString().slice(0,10)}"`)}${field('Seller','seller','text',c.seller,'maxlength="160"')}${notesField(c.notes)}<div class="full">${check('I verified the exact printing and the recorded condition or grade.','condition_confirmed',c.condition_confirmed||c.psa10_confirmed)}</div></div>`,async form=>{const d=formObject(form);Object.assign(d,parseCondition(form));delete d.condition_bucket;for(const k of ['purchase_price','shipping','fees','import_cost'])d[k]=nullableNumber(d[k]);d.purchase_date=d.purchase_date||null;d.condition_confirmed=form.elements.condition_confirmed.checked;d.psa10_confirmed=false;d.variant_id=vid;await api(existing?'/api/copies/'+existing.id:'/api/copies',{method:existing?'PUT':'POST',body:d});return 'Copy saved. PSA 10 and any-condition progress remain separate.';});}
function watchModal(vid){const w=state.watchlist.find(x=>x.variant_id===vid)||{};const initial='graded:PSA:10:Gem Mint:current';openModal('Watch this exact printing','Targets are total delivered prices in the selected currency. Saving one target preserves the others. Blank removes only the selected target.',`<div class="form-grid">${selectField('Target condition / grade','condition_bucket',conditionOptions(initial))}${field('Delivered-price target (optional)','target_amount','number',(w.targets||{})[initial]??w.target_price,'min="0" step="0.01"')}${selectField('Currency','currency',currencies(w.currency||state.preferences.currency))}${selectField('Collection priority','priority',[1,2,3,4,5].map(n=>opt(n,String(n)+(n===5?' — Highest':''),w.priority||1)).join(''))}${selectField('Fallback monitoring for this card','fallback_mode',opt('inherit','Use global settings',w.fallback_enabled==null?'inherit':String(w.fallback_enabled))+opt('true','Enabled',String(w.fallback_enabled))+opt('false','PSA 10 only',String(w.fallback_enabled)))}<label class="field full">Per-card fallback categories (empty = inherit global list)<select aria-label="Per-card fallback categories" name="fallback_buckets" multiple size="6">${conditionOptions(w.fallback_buckets||[],true)}</select></label>${notesField(w.notes)}</div><div class="notice info">Existing targets: ${Object.entries(w.targets||{}).map(([k,v])=>e(bucketLabel(k))+' '+money(v,w.currency)).join(' · ')||'None'}${w.target_price!=null?' · legacy PSA 10 target '+money(w.target_price,w.currency):''}</div>`,async form=>{const x=formObject(form),targets={...(w.targets||{})},amount=nullableNumber(x.target_amount);if(amount==null)delete targets[x.condition_bucket];else targets[x.condition_bucket]=amount;const buckets=[...form.elements.fallback_buckets.selectedOptions].map(o=>o.value);const changedCurrency=w.currency&&w.currency!==x.currency&&(Object.keys(targets).some(k=>k!==x.condition_bucket)||(w.target_price!=null&&x.condition_bucket!==initial));if(changedCurrency)throw new Error('Existing targets use another currency. Keep that currency or clear those targets before changing it.');await api('/api/watchlist',{method:'PUT',body:{variant_id:vid,target_price:x.condition_bucket===initial?amount:(w.target_price??null),targets,currency:x.currency,priority:Number(x.priority),notes:x.notes,fallback_enabled:x.fallback_mode==='inherit'?null:x.fallback_mode==='true',fallback_buckets:buckets.length?buckets:null}});return 'Condition-specific targets and card preferences saved.';});}
function listingModal(vid,l={}){openModal(l.id?'Update a real observation':'Add a source-linked listing','Record the exact offer and original condition wording. Updating resets its review. Blank costs remain unknown; zero means verified zero.',`<div class="form-grid">${conditionForm(l)}${field('Source / marketplace','source','text',l.source||'Manual','required maxlength="60"')}${selectField('Listing type','listing_type',opt('fixed','Fixed price',l.listing_type||'fixed')+opt('auction','Auction — current bid only',l.listing_type))}${field('Exact listing title','title','text',l.title,'required maxlength="400"')}${field('Direct listing URL','url','url',l.url,'required placeholder="https://…"')}${field('Seller photograph URL (optional)','image_url','url',l.image_url)}${field('Seller','seller','text',l.seller)}${field('Seller country (optional ISO code)','seller_country','text',l.seller_country,'pattern="[A-Z]{2}" maxlength="2"')}${field('Seller positive feedback percentage (optional)','seller_feedback','number',l.seller_feedback,'min="0" max="100" step="0.01"')}${costsForm(l)}${field('Delivery destination country','destination_country','text',l.destination_country||state.preferences.country,'required pattern="[A-Z]{2}" maxlength="2"')}${selectField('Delivery eligibility','delivery_eligible',opt('','Unknown',l.delivery_eligible==null?'':String(l.delivery_eligible))+opt('true','Confirmed deliverable',String(l.delivery_eligible))+opt('false','Not deliverable',String(l.delivery_eligible)))}${field('Auction end ISO timestamp (optional)','end_at','text',l.end_at,'placeholder="2026-11-01T18:00:00+00:00"')}${field('Certificate visible in source (optional)','cert','text',l.cert,'maxlength="32"')}${field('Cost assumptions / tax inclusion','cost_notes','text',l.cost_notes,'maxlength="1000"')}${notesField(l.notes)}</div>`,async form=>{const d=formObject(form);Object.assign(d,parseCondition(form));delete d.condition_bucket;for(const k of ['price','shipping','fees','import_cost','seller_feedback'])d[k]=nullableNumber(d[k]);d.delivery_eligible=d.delivery_eligible===''?null:d.delivery_eligible==='true';d.variant_id=vid;await api('/api/listings',{method:'POST',body:d});return 'Observation saved; identity and condition review still required.';});}
function saleModal(vid){if(!resolvedCard(vid))return;openModal('Add completed-sale evidence','Only disclosed completed transactions of this exact printing and condition enter its reference. Keep the original condition scale; an aggregate guide is not a sale.',`<div class="form-grid">${conditionForm()}${field('Source','source','text','','required')}${field('Evidence URL','source_url','url','','required')}${field('Transaction / lot identifier','transaction_id','text','','maxlength="160"')}${field('Sold date','sold_date','date','',`required max="${new Date().toISOString().slice(0,10)}"`)}${field('Disclosed item price (not shipping)','item_price','number','','min="0.01" step="0.01"')}${selectField('Sale currency','currency',currencies(state.preferences.currency))}${field('Certificate (when documented)','cert','text','','maxlength="32"')}${notesField()}<div class="full">${check('The actual transaction price is disclosed.','price_disclosed')}${check('This transaction is completed, not an active asking price.','completed')}${check('I checked the exact card printing and language.','exact_variant_confirmed')}${check('I checked the condition, grading company, grade and applicable designation/scale.','condition_confirmed')}</div></div>`,async form=>{const d=formObject(form);Object.assign(d,parseCondition(form));delete d.condition_bucket;for(const k of ['price_disclosed','completed','exact_variant_confirmed','condition_confirmed'])d[k]=form.elements[k].checked;d.item_price=nullableNumber(d.item_price);d.variant_id=vid;await api('/api/sales',{method:'POST',body:d});return 'Source-linked sale saved; like-for-like eligibility is evaluated separately.';});}
function reviewModal(vid,l){if(!resolvedCard(vid))return;const raw=l.grader==='RAW';openModal(raw?'Review the exact card':'Review the exact slab','Review the actual photographs and evidence. This is your attestation, not automatic authentication. Correct conflicting source information before reviewing.',`<div class="notice info"><a href="${e(l.url)}" target="_blank" rel="noopener noreferrer">Open original listing ↗</a><p>${e(l.title)}</p><strong>${e(l.condition_label||conditionText(l))}</strong></div><div class="form-grid">${raw?'':field('Certification number (graded copies only)','cert','text',l.match?.cert||l.cert,'required maxlength="32"')}<label class="field full">What did you check?<textarea name="notes" minlength="12" maxlength="2000" required rows="3">${e(l.match?.notes||'')}</textarea></label></div>${check('The card is exactly this printing, language, edition, finish and stamp.','identity_confirmed')}${check('I checked the available seller photographs.','photo_checked')}${raw?check('I checked the raw condition against the stated source scale.','condition_checked'):check('The slab label agrees with this company, numeric grade, designation and scale.','label_checked')+check('I checked that the certification details agree with the slab.','cert_checked')}`,async form=>{const d=formObject(form);for(const k of ['identity_confirmed','photo_checked','label_checked','cert_checked','condition_checked'])d[k]=form.elements[k]?.checked||false;d.cert=d.cert||'';d.variant_id=vid;await api('/api/listings/'+l.id+'/review',{method:'POST',body:d});return 'Owner-reviewed identity and condition saved.';},'Save review');}
function variantModal(v={}){openModal(v.id?'Document an exact printing':'Add a documented printing','Use release documentation for every identity distinction. Creating a resolved printing retires the unresolved placeholder, without deleting its records.',`<div class="form-grid">${field('Card name','name','text',v.name||'Charmander','required maxlength="150"')}${selectField('Language','language',Object.entries(state.languages).map(([k,n])=>opt(k,n,v.language||'en')).join(''))}${field('Set name','set_name','text',v.set_name,'required')}${field('Set code (stable)','set_code','text',v.set_code,'required')}${field('Card number, including denominator','number','text',v.number,'required')}${field('Release year (blank = unknown)','year','number',v.year,'min="1996" max="2100"')}${field('Edition','edition','text',v.edition==='unspecified'?'':v.edition||'standard','required placeholder="standard / unlimited / 1st edition…"')}${field('Exact finish / foil treatment','finish','text',v.finish==='unspecified'?'':v.finish,'required placeholder="normal / reverse-holo / cosmos-holo…"')}${field('Stamp (none if absent)','stamp','text',v.stamp||'none','required')}${field('Print run / distinguishing release','print_run','text',v.print_run||'standard','required')}${selectField('Size','size',opt('standard','Standard',v.size||'standard')+opt('jumbo','Jumbo',v.size))}${selectField('Release type','release_type',['Expansion','Promo','Deck','Jumbo'].map(x=>opt(x,x,v.release_type||'Expansion')).join(''))}${field('Catalogue / release evidence URL','source_url','url',v.source_url,'required')}${field('Reference artwork URL (optional)','image_url','url',v.image_url)}${notesField(v.notes)}<div class="full">${check('Artwork-only cameo rather than a named Charmander card','artwork_only',v.artwork_only)}${check('Announced future release','announced',v.announced)}</div></div>`,async form=>{const d=formObject(form);d.year=nullableNumber(d.year);for(const k of ['artwork_only','announced'])d[k]=form.elements[k].checked;d.base_id=v.base_id||`${d.language}:${d.set_code}:${d.number}`;d.identity_status='documented';await api('/api/catalogue',{method:'POST',body:d});return 'Exact printing saved with a stable identity.';});}
function photoModal(id){openModal('Add your actual slab photo','Private JPG, PNG or WebP. Images are re-encoded without embedded metadata. The maximum upload is 5 MB and 20 megapixels.',`<label class="field">Choose a photograph<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label>`,async form=>{const data=new FormData();data.append('file',form.elements.photo.files[0]);await api('/api/copies/'+id+'/photo',{method:'POST',body:data});return 'Private slab photo saved.';},'Upload photo');}
function importModal(){openModal('Import your records','CSV imports are validated before an atomic commit. Use stable variant IDs from card details. Export files round-trip into an empty collection; duplicate certificates are rejected.',`<div class="form-grid">${selectField('Record type','kind',['copies','watchlist','listings','sales'].map(x=>opt(x,x,'copies')).join(''))}<label class="field">CSV file<input name="file" type="file" accept=".csv,text/csv" required></label></div><p><a id="template-link" href="/api/import/template/copies">Get empty CSV template ↧</a></p>`,async form=>{const kind=form.elements.kind.value;const file=form.elements.file.files[0];if(file.size>1_000_000)throw new Error('CSV is larger than 1 MB.');const text=await file.text();const preview=await api('/api/import',{method:'POST',body:{kind,csv_text:text,commit:false}});if(!preview.ok)throw new Error(preview.errors.map(x=>`Row ${x.row}: ${x.message}`).join('\n'));openModal('Confirm validated import',`${preview.rows} ${kind} rows passed validation. No records have been imported yet.`,`<div class="notice info">The entire batch will be saved, or nothing will be changed. Importing does not authenticate seller or PSA claims.</div>`,async()=>{const result=await api('/api/import',{method:'POST',body:{kind,csv_text:text,commit:true}});if(!result.ok)throw new Error(result.errors.map(x=>x.message).join('\n'));return `${result.rows} records imported.`;},'Import records');return false;},'Validate CSV');}
async function findListing(id,vid){const d=activeCard?.card.id===vid?activeCard:await api('/api/cards/'+vid);return d.listings.find(x=>x.id===id);}
async function reloadState(){state=await api('/api/state');csrf=state.csrf;}
async function renderRoute(){if(!state)return;const epoch=++routeEpoch;const route=(location.hash||'#dashboard').slice(1);let content;try{if(route.startsWith('card/'))content=await detailPage(decodeURIComponent(route.slice(5)));else if(route==='collection')content=binder();else if(route==='deals')content=await dealsPage();else if(route==='plan')content=await plannerPage();else if(route==='watchlist')content=watchlistPage();else if(route==='settings')content=settingsPage();else if(route==='alerts')content=await alertsPage();else content=await dashboard();if(epoch!==routeEpoch)return;root.innerHTML=shell(content);if(route==='collection')renderBinderResults();attachImages();document.title=`${route.startsWith('card/')?activeCard?.card.name:route[0].toUpperCase()+route.slice(1)} · Ember`;}catch(err){if(epoch!==routeEpoch)return;if(!state)return;root.innerHTML=shell(empty('This page could not load',err.message,act('retry','Try again','button')));}}
async function refresh(){await reloadState();await renderRoute();}
window.addEventListener('hashchange',()=>{renderRoute();window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('input',event=>{if(event.target.dataset.dealFilter){dealFilters[event.target.dataset.dealFilter]=event.target.value;document.querySelector('#deal-results').innerHTML=dealResults();return;}if(event.target.dataset.filter){filters[event.target.dataset.filter]=event.target.value;filters.page=1;renderBinderResults();}});
document.addEventListener('change',event=>{if(event.target.id==='saved-search'){const saved=(state.saved_searches||[]).find(x=>x.id===event.target.value);if(saved){Object.assign(filters,saved.filters,{page:1});renderRoute();}return;}if(event.target.id==='history-bucket'){historySelection=event.target.value;document.querySelector('#condition-history').innerHTML=historyPanel(activeCard,historySelection);return;}if(event.target.name==='condition_bucket'&&event.target.form?.elements.target_amount){const w=state.watchlist.find(w=>w.variant_id===activeCard?.card.id)||{};event.target.form.elements.target_amount.value=(w.targets||{})[event.target.value]??(event.target.value==='graded:PSA:10:Gem Mint:current'?w.target_price:'')??'';}if(event.target.name==='kind'&&event.target.form?.id==='modal-form'){const link=document.querySelector('#template-link');if(link)link.href='/api/import/template/'+event.target.value;}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['login-form','setup-form','modal-form','settings-form'].includes(form.id))return;event.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';
 try{
  if(form.id==='setup-form'){const password=form.elements.password.value;await api('/api/setup',{method:'POST',body:{password,confirmation:form.elements.confirmation.value}});const result=await api('/api/login',{method:'POST',body:{password}});csrf=result.csrf;await refresh();}
  else if(form.id==='login-form'){const result=await api('/api/login',{method:'POST',body:{password:form.elements.password.value}});csrf=result.csrf;form.elements.password.value='';await refresh();}
  else if(form.id==='settings-form'){const data=formObject(form);const p={...state.preferences,...data};p.languages=[...new FormData(form).getAll('languages')];p.release_types=[...new FormData(form).getAll('release_types')];delete p.release_type;for(const k of ['finishes','editions','stamps'])p[k]=data[k].split(',').map(x=>x.trim()).filter(Boolean);p.sizes=data.sizes?[data.sizes]:[];for(const k of ['paused','notifications','artwork_only','include_announced'])p[k]=form.elements[k].checked;for(const k of ['refresh_hours','stale_hours','bargain_pct','expensive_pct','min_sales','lookback_days','half_life_days'])p[k]=Number(p[k]);p.budget=nullableNumber(p.budget);p.fallback_enabled=form.elements.fallback_enabled.checked;p.fallback_buckets=[...new FormData(form).getAll('fallback_buckets')];p.min_seller_feedback=nullableNumber(p.min_seller_feedback);p.seller_countries=(data.seller_countries||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);await api('/api/settings',{method:'PUT',body:p});toast('Preferences saved.');await refresh();}
  else if(modalSubmit){const result=await modalSubmit(form);if(result!==false){modal.close();toast(typeof result==='string'?result:'Saved.');await refresh();}}
 }catch(err){if(error?.isConnected)error.textContent=err.message;else toast(err.message);}finally{busy=false;if(button?.isConnected)button.disabled=false;}
});
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id,vid=button.dataset.vid||activeCard?.card.id;
 if(action==='close-modal'){modal.close();return;}if(busy)return;
 try{
  if(action==='status-filter'){filters.status=button.dataset.value;filters.page=1;await renderRoute();return;}
  if(action==='page-prev'||action==='page-next'){filters.page=Math.max(1,filters.page+(action==='page-next'?1:-1));renderBinderResults();return;}
  if(action==='save-search'){openModal('Save this search','Store the current binder filters.',field('Search name','name','text','','required maxlength=80'),async form=>{await api('/api/saved-searches',{method:'POST',body:{name:form.elements.name.value,filters:{...filters,page:1}}});return 'Search saved.';});return;}
  if(action==='delete-search'){await api('/api/saved-searches/'+id,{method:'DELETE'});await refresh();return;}
  if(action==='add-copy'){copyModal(vid);return;}
  if(action==='edit-copy'){const c=state.copies.find(x=>x.id===id);copyModal(c.variant_id,c);return;}
  if(action==='watch'){watchModal(vid);return;}
  if(action==='add-listing'){listingModal(vid);return;}
  if(action==='edit-listing'){listingModal(vid,await findListing(id,vid));return;}
  if(action==='review-listing'){reviewModal(vid,await findListing(id,vid));return;}
  if(action==='add-sale'){saleModal(vid);return;}
  if(action==='add-variant'){variantModal();return;}
  if(action==='resolve-variant'){variantModal(activeCard.card);return;}
  if(action==='photo'){photoModal(id);return;}
  if(action==='import'){importModal();return;}
  if(action==='connect-pricecharting'){openModal('Configure existing PriceCharting token','Use only an existing licensed API token. This does not buy a subscription. Access is tested on the first explicit product refresh.',field('API token','token','password','','required autocomplete="off"'),async form=>{await api('/api/sources/pricecharting',{method:'PUT',body:formObject(form)});return 'Token encrypted; access not yet verified.';});return;}
 if(action==='disconnect-pricecharting'){openModal('Disconnect and purge price-guide estimates','Cached provider estimates must be removed when your subscription ends. Your collection and completed-sale evidence are preserved.','<p>Remove the token and all cached PriceCharting estimates?</p>',async()=>{await api('/api/sources/pricecharting',{method:'DELETE'});return 'PriceCharting disconnected and cached estimates removed.';},'Confirm');return;}
 if(action==='public-guides'){const v=activeCard.card;openModal('Refresh free public guides','No API key or subscription. Provider averages may mix conditions, languages and printings; they remain context only.',`${field('TCGdex card ID','provider_id','text',v.provider_id||v.set_code+'-'+v.number.split('/')[0],'required pattern="[A-Za-z0-9_-]{1,100}"')}${check('I checked this TCGdex base card; I understand its guide does not verify this exact printing or condition.','base_card_confirmed')}`,async form=>{const d=formObject(form);d.base_card_confirmed=form.elements.base_card_confirmed.checked;const r=await api('/api/cards/'+vid+'/public-guides',{method:'POST',body:d});return r.message;});return;}
 if(action==='pricecharting-product'){openModal('Refresh a PriceCharting product','Current aggregate estimates only. Confirm this product is the exact language and printing; never use a loose match.',`${field('PriceCharting numeric product ID','product_id','text','','required pattern="[0-9]{1,12}"')}${check('I checked that this product matches the exact printing and language.','product_identity_confirmed')}`,async form=>{const d=formObject(form);d.product_identity_confirmed=form.elements.product_identity_confirmed.checked;d.variant_id=vid;const r=await api('/api/sources/pricecharting/product',{method:'POST',body:d});return `${r.observations.length} aggregate observations retrieved, excluded from sale valuations.`;});return;}
 if(action==='connect-ebay'){openModal('Connect eBay Browse','Eligible production Client ID and Client Secret are required. Both OAuth and Browse access are tested before encrypted storage.',`<div class="form-grid">${field('Production Client ID','client_id','text','','required autocomplete="off"')}${field('Production Client Secret','client_secret','password','','required autocomplete="off"')}</div>`,async form=>{const r=await api('/api/sources/ebay',{method:'POST',body:formObject(form)});if(r.status!=='connected')throw new Error(r.message);return 'Production Browse connection verified.';},'Test and connect');return;}
  if(['delete-copy','delete-sale','unwatch','disconnect-ebay','unavailable'].includes(action)){
   const label={'delete-copy':'Remove this ownership record and its photo?','delete-sale':'Remove this completed-sale observation?','unwatch':'Remove this watchlist target?','disconnect-ebay':'Remove your saved eBay credentials?','unavailable':'Mark this observation unavailable?'}[action];
   openModal(label,'This does not buy, sell, bid, or contact anyone. Keep an export or backup before removing records.',`<p>${action==='unavailable'?'This does not establish a completed sale.':'The selected record will be removed from this application.'}</p>`,async()=>{const paths={'delete-copy':'/api/copies/'+id,'delete-sale':'/api/sales/'+id,'unwatch':'/api/watchlist/'+vid,'disconnect-ebay':'/api/sources/ebay','unavailable':'/api/listings/'+id+'/unavailable'};await api(paths[action],{method:action==='unavailable'?'POST':'DELETE'});return 'Change saved.';},'Confirm');return;
  }
  busy=true;button.disabled=true;
  if(action==='logout'){await api('/api/logout',{method:'POST'});state=null;csrf='';loginView();return;}
  if(action==='monitor'){toast('Checking the updater and saved preferences…');const result=await api('/api/monitor',{method:'POST',body:{force:true}});const proof=await api('/api/monitor');if(result.status!=='busy'&&proof.last_execution?.checkedAt!==result.checkedAt)throw new Error('Updater returned, but the persisted timestamp did not match.');toast(`${result.status}: ${result.message}`);}
  else if(action==='scan-card'){const r=await api('/api/cards/'+encodeURIComponent(vid)+'/scan',{method:'POST'});toast(`${r.status}: ${r.message}`);}
  else if(action==='refresh-fx'){const r=await api('/api/sources/fx',{method:'POST'});toast(r.message||r.status||(r.rates?'Reference exchange rates refreshed.':'Source response received.'));}
  else if(action==='sync-catalogue'){const lang=document.querySelector('#catalogue-language').value;toast('Fetching the next bounded catalogue batch…');const r=await api('/api/catalogue/sync/'+lang,{method:'POST'});toast(`${r.status}: ${r.added||0} records added; ${(r.errors||[]).length} errors.`);}
  else if(action==='read-alerts'){await api('/api/alerts/read',{method:'POST'});toast('Alerts marked read.');}
  else if(action==='monitor-history'){const r=await api('/api/monitor');openModal('Updater execution log','These are persisted executions. A paused execution or an access error is not a successful marketplace scan.',r.history.length?r.history.map(x=>`<div class="notice"><strong>${e(x.status)}</strong> · ${e(x.trigger)} · ${e(dt(x.checkedAt))}<p>${e(x.message)} · ${x.scanned_variants||0} variants scanned · ${x.new_alerts||0} new alerts.</p><p>${e((x.errors||[]).join('; '))}</p></div>`).join(''):empty('No executions recorded','Run the updater or allow the configured scheduler to wake.'));return;}
  await refresh();
 }catch(err){toast(err.message);}finally{busy=false;if(button.isConnected)button.disabled=false;}
});
let historySelection='';
let dealRows=[];
const dealFilters={q:'',grader:'',condition:'',language:'',type:'',max:'',country:'',confidence:''};
function clientConditionKey(x={}){const g=x.grader||'PSA';if(g==='RAW')return `raw:${x.condition_scale||'seller'}:${x.raw_condition||'Unknown'}`;if(g==='UNKNOWN'||x.grade===null)return 'unknown';const grade=x.grade??10;let d=x.designation||'';if(g==='PSA')d=Number(grade)===10?'Gem Mint':Number(grade)===9?'Mint':'';if(g==='BGS'&&Number(grade)===9.5)d='Gem Mint';return `graded:${g}:${Number(grade)}:${d}:${x.grading_scale||'current'}`;}
function bucketLabel(k){return state.condition_options.find(o=>o.key===k)?.label||k;}
function conditionText(x={}){return bucketLabel(clientConditionKey(x));}
function conditionOptions(current,multiple=false){let out='';const options=state.condition_options||[];const groups=[...new Set(options.map(o=>o.fields.grader==='RAW'?'Raw · '+o.fields.condition_scale:o.fields.grader))];for(const g of groups){out+=`<optgroup label="${e(g)}">`;for(const o of options.filter(o=>(o.fields.grader==='RAW'?'Raw · '+o.fields.condition_scale:o.fields.grader)===g)){out+=`<option value="${e(o.key)}" ${(multiple?current.includes(o.key):current===o.key)?'selected':''}>${e(o.label)}</option>`;}out+='</optgroup>';}return out;}
function conditionForm(row={}){return `${selectField('Condition / grading category','condition_bucket',opt('unknown','Unknown — review needed',clientConditionKey(row))+conditionOptions(clientConditionKey(row)))}${field('Original condition wording / slab description','condition_original','text',row.condition_original,'maxlength="300"')}<p class="footnote full">Raw conditions use the named source scale. Seller “Mint” is not PSA 10. CGC eras and BGS/CGC designations are distinct categories; select what the actual label supports.</p>`;}
function parseCondition(form){const key=form.elements.condition_bucket.value;const option=state.condition_options.find(o=>o.key===key);return option?{...option.fields,condition_original:form.elements.condition_original?.value||''}:{grader:'UNKNOWN',grade:null,designation:'',grading_scale:'current',raw_condition:'Unknown',condition_scale:'seller',condition_original:form.elements.condition_original?.value||''};}
function scatterChart(points,currency,title){if(!points.length)return '';const valid=points.filter(p=>Number.isFinite(p.value)&&Number.isFinite(Date.parse(p.date)));if(!valid.length)return '';const vals=valid.map(p=>p.value),times=valid.map(p=>Date.parse(p.date)),min=Math.min(...vals)*.9,max=Math.max(...vals)*1.1||1,t0=Math.min(...times),t1=Math.max(...times);return `<figure class="observation-chart"><svg class="chart" viewBox="0 0 600 180" role="img" aria-label="${e(title)}"><line x1="65" x2="580" y1="145" y2="145" stroke="currentColor" opacity=".25"/>${valid.map(p=>{const x=t0===t1?320:70+500*(Date.parse(p.date)-t0)/(t1-t0),y=135-110*(p.value-min)/(max-min||1);return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="5" fill="currentColor"><title>${e(p.label)} · ${e(money(p.value,currency))}</title></circle>`;}).join('')}<text x="5" y="22" font-size="11">${e(money(max,currency))}</text><text x="5" y="140" font-size="11">${e(money(min,currency))}</text><text x="65" y="169" font-size="11">${e(new Date(t0).toISOString().slice(0,10))}</text><text x="505" y="169" font-size="11">${e(new Date(t1).toISOString().slice(0,10))}</text></svg><figcaption class="footnote">${e(title)} · ${valid.length} real recorded observation(s). Points are not interpolated into a daily price series.</figcaption></figure>`;}
function historyPanel(d,key){const m=d.markets[key];if(!m)return '';const observations=d.price_observations.filter(o=>o.condition_key===key);const asks=observations.filter(o=>o.observation_type==='asking_price');const bids=observations.filter(o=>o.observation_type==='auction_bid');return `<div class="status-line">${tag(m.confidence+' price confidence',m.reference?'green':'orange')}<span>${m.count} eligible sales</span></div><p>${e(m.reason)}</p>${m.reference!=null?`<p>Reference ${money(m.reference)} · weighted 25th–75th percentile range ${money(m.range[0])}–${money(m.range[1])}; not a confidence interval.</p>`:''}${priceChart(m)}${m.included.length||m.excluded.length?salesTable(m):''}<details class="evidence"><summary>Method and comparability</summary><p>${e(m.method)}</p><p>Different grading companies, numeric grades, designations, grading eras and raw-condition scales are excluded—not treated as equivalent.</p></details><details class="evidence"><summary>Separate asking-price / auction-bid observations (${observations.length})</summary><p>These observations are not realized prices and never enter the sale reference.</p>${['asking_price','auction_bid'].map(type=>{const rows=type==='asking_price'?asks:bids;return [...new Set(rows.map(o=>o.currency))].map(c=>scatterChart(rows.filter(o=>o.currency===c).map(o=>({date:o.observed_at,value:o.price,label:type+' · '+o.source})),c,type==='asking_price'?'Asking-price observations (original currency)':'Auction-bid observations (not final prices)')).join('');}).join('')}${observations.length?`<div class="table-wrap"><table><thead><tr><th>Observed</th><th>Type / source</th><th>Item price</th></tr></thead><tbody>${observations.map(o=>`<tr><td>${e(dt(o.observed_at))}</td><td><a href="${e(o.url)}" target="_blank" rel="noopener noreferrer">${e(o.observation_type)} · ${e(o.source)} ↗</a></td><td>${money(o.price,o.currency)}</td></tr>`).join('')}</tbody></table></div>`:''}</details>`;}
function comparisonTable(d){const best=new Set(d.best_by_condition.map(b=>b.best_listing_id).filter(Boolean));const fixed=d.listings.filter(l=>l.listing_type==='fixed');if(!fixed.length)return '';return `<h3>Cross-platform comparison</h3><div class="table-wrap"><table><thead><tr><th>Condition / grade</th><th>Source / seller</th><th>Asking</th><th>Total delivered</th><th>Evidence / preference</th><th></th></tr></thead><tbody>${fixed.map(l=>`<tr class="${best.has(l.id)?'best-row':''}"><td>${e(l.condition_label)}${best.has(l.id)?'<br><strong>Best confirmed total in this category</strong>':''}</td><td>${e(l.source)}<br>${e(l.seller||'Unknown')}</td><td>${money(l.price,l.currency)}</td><td>${l.assessment.cost.total!=null?money(l.assessment.cost.total):'Incomplete · '+(l.assessment.cost.lower_bound!=null?'≥ '+money(l.assessment.cost.lower_bound):'unknown')}</td><td>${e(l.assessment.label)}<br>${e(l.assessment.price_confidence)} price confidence · ${l.assessment.preference_eligible?'enabled category':'not enabled'}${l.assessment.within_budget?'':' · outside/unknown budget'}</td><td><a href="${e(l.url)}" target="_blank" rel="noopener noreferrer">View offer ↗</a></td></tr>`).join('')}</tbody></table></div>`;}
function dealResults(){const f=dealFilters;const rows=dealRows.filter(d=>{const l=d.listing,a=l.assessment;return (!f.q||[d.card.name,d.card.number,d.card.set_name,l.title].join(' ').toLowerCase().includes(f.q.toLowerCase()))&&(!f.grader||l.grader===f.grader)&&(!f.condition||l.condition_key===f.condition)&&(!f.language||d.card.language===f.language)&&(!f.type||l.listing_type===f.type)&&(!f.max||(a.cost.total!=null&&a.cost.total<=Number(f.max)))&&(!f.country||l.seller_country===f.country.toUpperCase())&&(!f.confidence||a.price_confidence===f.confidence);});return `<p class="footnote">${rows.length} offers in this view. Only enabled categories still needed for your collection are included.</p>${rows.length?rows.map(d=>`<section class="panel"><h2><a href="#card/${e(d.card.id)}">${e(d.card.set_name)} · ${e(d.card.number)}</a></h2><p>${e(state.languages[d.card.language])} · ${e(d.card.finish)} · priority ${d.priority}</p>${listingCard(d.listing,d.card.id)}</section>`).join(''):empty('No matching buying opportunities','Change these filters, enable fallback categories in Settings, or add real source-linked listings for missing cards. No demonstration offers are shown.')}`;}
function settingsPage(){const p=state.preferences;let html=baseSettingsPage();const extra=`<section class="panel wide"><h2>PSA 10 & fallback buying preferences</h2><p>PSA 10 always remains the completion goal. Alternative ownership is counted separately; raw source scales and grading designations remain distinct.</p><div class="form-grid">${check('Enable alternative conditions and grades','fallback_enabled',p.fallback_enabled)}${selectField('Opportunity ranking','buying_priority',opt('psa_first','PSA 10 and preferred categories first',p.buying_priority)+opt('value_first','Evidence-led value first (category always shown)',p.buying_priority))}<label class="field full">Allowed fallback categories<select aria-label="Allowed fallback categories" name="fallback_buckets" multiple size="9">${conditionOptions(p.fallback_buckets||[],true)}</select><small>Use Ctrl / Command to select multiple options. Per-card watchlist settings may override these.</small></label>${field('Minimum seller positive feedback (%) — optional','min_seller_feedback','number',p.min_seller_feedback,'min="0" max="100" step="0.01"')}${field('Allowed seller countries (comma-separated; blank = all)','seller_countries','text',(p.seller_countries||[]).join(', '))}</div><p class="footnote">A required seller location or feedback value that is missing makes an offer ineligible. Buying one enabled fallback stops further fallback alerts but keeps PSA 10 upgrade monitoring active.</p></section>`;html=html.replace('<section class="panel wide"><h2>Monitoring & alerts</h2>',extra+'<section class="panel wide"><h2>Monitoring & alerts</h2>');html+=`<section class="panel"><h2>Source capability inventory</h2><p>Research checked 10 October 2026. Connection status, returned coverage and a successful scan are separate facts.</p><div class="source-grid">${state.source_inventory.map(s=>`<div class="source-box"><h3>${e(s.name)}</h3>${tag(s.state.status,s.state.status==='connected'?'green':'orange')}<p>${e(s.access)}</p><p>${e(s.data)}</p><details><summary>Access, coverage and limitations</summary><p>${e(s.coverage)}</p><p>${e(s.requirements)}</p><p>${e(s.frequency)}</p><p>${e(s.limitations)}</p>${s.docs?`<a href="${e(s.docs)}" target="_blank" rel="noopener noreferrer">Provider documentation ↗</a>`:''}<p>Last checked: ${e(dt(s.state.checked_at))}</p></details>${s.id==='pricecharting'?`<div class="actions">${act('connect-pricecharting','Configure existing token','button-outline button-small')}${act('disconnect-pricecharting','Disconnect & purge estimates','button-subtle button-small')}</div>`:''}</div>`).join('')}</div></section>`;return html;}

(async()=>{try{const boot=await api('/api/bootstrap');if(boot.setup_required){setupView();return;}await reloadState();await renderRoute();}catch{state=null;loginView();}})();

function setupView(){
 root.innerHTML=`<div class="login-layout"><section class="login-art"><div class="brand"><span class="brand-symbol">e.</span><div><strong>ember</strong><small>The Charmander collection</small></div></div><div class="eyebrow">A little fire. A lifelong collection.</div><h1>Every Charmander.<br>Your own pace.</h1><p>A private binder, a patient deal radar, and the evidence behind each price. Start with English and French, in NM/Mint or PSA 10.</p></section><main class="login-form"><div class="eyebrow">First launch on this Mac</div><h2>Make this binder yours.</h2><p>Choose a password to protect your local collection. Your cards, photographs and marketplace settings stay on this computer.</p><form id="setup-form"><label class="field">Choose owner password<input name="password" type="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label><label class="field">Repeat password<input name="confirmation" type="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label><p class="footnote">Use at least 12 characters. There is no online account to create.</p><p class="form-error" role="alert"></p><button class="button" type="submit">Create my private binder ↗</button></form></main></div>`;
}
function savedSearchControls(){const rows=state.saved_searches||[];return `<section class="saved-searches"><label class="field">Saved searches<select id="saved-search"><option value="">Choose a saved search…</option>${rows.map(x=>opt(x.id,x.name,'')).join('')}</select></label>${act('save-search','Save current filters','button-outline button-small')}${rows.length?`<details><summary>Manage saved searches</summary>${rows.map(x=>`<div class="list-row"><span>${e(x.name)}</span>${act('delete-search','Remove','button-subtle button-small',`data-id="${e(x.id)}"`)}</div>`).join('')}</details>`:''}</section>`;}
function watchlistPage(){const watches=[...state.watchlist].sort((a,b)=>b.priority-a.priority);const cards=watches.map(w=>state.variants.find(v=>v.id===w.variant_id)).filter(Boolean);return `<div class="page-heading"><div><div class="eyebrow">Your next additions</div><h1>The watchlist.</h1><p>Priority cards and condition-specific targets within your current collection scope.</p></div><a class="button-outline" href="#collection">Find a card ↗</a></div>${cards.length?`<div class="grid">${cards.map(cardTile).join('')}</div>`:empty('Your watchlist starts here','Open a card and choose Set a target to save its priority and delivered-price targets.')}`;}
async function plannerPage(){const data=await api('/api/planner');const x=data.estimate;return `<div class="page-heading"><div><div class="eyebrow">Build the collection efficiently</div><h1>Your next purchases.</h1><p>Know what is missing, what has a price reference, and which sellers have several cards you need.</p></div><a href="#deals" class="button-outline">Open the radar ↗</a></div><section class="panel"><h2>The remaining PSA 10 goal</h2><div class="stats"><div class="stat"><div class="stat-top">MISSING VARIANTS</div><strong>${x.missing_psa10_variants}</strong></div><div class="stat"><div class="stat-top">WITH SALE REFERENCES</div><strong>${x.priced_variants}</strong></div><div class="stat"><div class="stat-top">WITHOUT ENOUGH EVIDENCE</div><strong>${x.unpriced_variants}</strong></div></div><p>${x.known_item_estimate==null?'There is not enough completed-sale evidence to estimate the remaining cost. Add exact-condition sales in card details or import a CSV.':`${x.complete?'Estimated item cost':'Known part of the item cost'}: <strong>${money(x.known_item_estimate,x.currency)}</strong> · descriptive reference range ${money(x.known_item_range[0],x.currency)}–${money(x.known_item_range[1],x.currency)}.`}</p><p class="footnote">${e(x.basis)} ${x.complete?'':'This is not a total budget for all missing cards.'}</p></section><div class="section-head"><h2>Several cards, one seller</h2></div><p>Only reviewed, current fixed-price offers in your enabled categories with complete individual delivered costs are grouped. Each variant appears once per seller.</p>${data.seller_groups.length?data.seller_groups.map(g=>`<section class="panel"><h3>${e(g.seller)} · ${e(g.source)}</h3>${tag(g.variants+' missing variants')}${tag(g.within_budget?'Within the recorded budget':'Basket exceeds or cannot be checked against budget',g.within_budget?'green':'orange')}<ul>${g.items.map(item=>`<li><a href="${e(item.url)}" target="_blank" rel="noopener noreferrer">${e(item.title)} ↗</a></li>`).join('')}</ul><p>Separate purchases: <strong>${money(g.individual_total,g.currency)}</strong> including ${money(g.separate_shipping,g.currency)} in postage.</p><p>${e(g.message)}</p><label class="field">Seller’s quoted combined shipping (${e(g.currency)})<input type="number" min="0" max="100000000" step="0.01" placeholder="Enter an actual quote" data-bundle-base="${g.individual_total-g.separate_shipping}" data-bundle-shipping="${g.separate_shipping}" data-bundle-currency="${e(g.currency)}"></label><p class="bundle-result footnote" aria-live="polite">A combined total appears after you enter a quote.</p></section>`).join(''):empty('No same-seller groups yet','Connect eBay or add real listings, review their exact cards and delivery costs, and Ember will group sellers with several missing variants.')}`;}
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.bundleBase==null)return;const target=input.closest('.panel').querySelector('.bundle-result');if(input.value===''){target.textContent='A combined total appears after you enter a quote.';return;}const quote=Number(input.value);if(!Number.isFinite(quote)||quote<0){target.textContent='Enter a nonnegative shipping quote.';return;}const currency=input.dataset.bundleCurrency;const total=Number(input.dataset.bundleBase)+quote;const difference=Number(input.dataset.bundleShipping)-quote;target.textContent=`If item prices, fees and import charges stay unchanged: ${money(total,currency)} combined total; ${money(difference,currency)} postage saved versus separate purchases. Confirm the final basket with the seller.`;});
